def longest_pal_memo(s):
    n = len(s)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def is_pal(i, j):
        if j - i <= 1:                # 长度 1 或 2：只看两端字符
            return s[i] == s[j]
        # 去壳：两端相等且内部仍是回文
        return s[i] == s[j] and is_pal(i + 1, j - 1)
    best = (0, 0)                     # 记录最长回文的 (起点, 终点)
    for i in range(n):
        for j in range(i, n):
            if is_pal(i, j) and j - i > best[1] - best[0]:
                best = (i, j)
    return s[best[0]:best[1] + 1]

def longest_pal_table(s):
    n = len(s)
    dp = [[False] * n for _ in range(n)]   # dp[i][j] = s[i..j] 是否回文
    for i in range(n):
        dp[i][i] = True               # 长度 1 恒为回文
    start, max_len = 0, 1
    for length in range(2, n + 1):    # 外层按区间长度从小到大
        for i in range(0, n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and (length <= 3 or dp[i + 1][j - 1]):
                dp[i][j] = True
                if length > max_len:
                    start, max_len = i, length
    return s[start:start + max_len]

def longest_pal_expand(s):
    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1                    # 向左扩一格
            r += 1                    # 向右扩一格
        return r - l - 1              # 失配后回退，回文长度 r-l-1
    start, end = 0, 0
    for i in range(len(s)):
        m = max(expand(i, i), expand(i, i + 1))   # 字符位/字符间隙两种中心
        if m > end - start + 1:
            start, end = i - (m - 1) // 2, i + m // 2
    return s[start:end + 1]

