# ACM 模式：完整可运行程序（stdin -> stdout）
# 输入格式：
#   第一行：字符串 s（长度 >= 1，不含空白字符）
# 输出格式：一行一个字符串，s 的最长回文子串（若有多个输出任意一个）
import sys

def main():
    s = sys.stdin.read().split()[0]   # 读入字符串

    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return r - l - 1

    start, end = 0, 0
    for i in range(len(s)):
        m = max(expand(i, i), expand(i, i + 1))   # 字符位/间隙两种中心
        if m > end - start + 1:
            start, end = i - (m - 1) // 2, i + m // 2
    print(s[start:end + 1])

if __name__ == '__main__':
    main()

problems.codeCpp:
class Solution {
public:
    string longestPalindrome(string s) {
        // 状态定义：expand(l, r) 返回以 s[l..r] 为中心能扩展出的最长回文长度
        // （相当于区间 DP dp[i][j] 空间优化后的等价形式，避免 O(n^2) 存储）
        int n = (int)s.size();
        auto expand = [&](int l, int r) {   // 向两侧扩展
            while (l >= 0 && r < n && s[l] == s[r]) { --l; ++r; }
            return r - l - 1;               // 循环结束时已不回文，长度为 r-l-1
        };
        int start = 0, end = 0;             // 记录当前最长回文的左右端点
        for (int i = 0; i < n; ++i) {
            int m = max(expand(i, i), expand(i, i + 1));   // 字符位/间隙两种中心
            if (m > end - start + 1) {      // 发现更长的回文则更新端点
                start = i - (m - 1) / 2;
                end = i + m / 2;
            }
        }
        return s.substr(start, end - start + 1);
    }
};

