problems.codeJava:
class Solution {
    public String longestPalindrome(String s) {
        // 状态定义：expand(l, r) 返回以 s[l..r] 为中心能扩展出的最长回文长度
        // （相当于区间 DP dp[i][j] 空间优化后的等价形式）
        int n = s.length();
        int start = 0, end = 0;          // 记录当前最长回文的左右端点
        for (int i = 0; i < n; i++) {
            int m = Math.max(expand(s, i, i), expand(s, i, i + 1));   // 字符位/间隙两种中心
            if (m > end - start + 1) {   // 发现更长的回文则更新端点
                start = i - (m - 1) / 2;
                end = i + m / 2;
            }
        }
        return s.substring(start, end + 1);
    }

    private int expand(String s, int l, int r) {   // 向两侧扩展
        while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) { l--; r++; }
        return r - l - 1;                          // 循环结束时已不回文，长度为 r-l-1
    }
}

