var longestPalindrome = function (s) {
  // 状态定义：expand(l, r) 返回以 s[l..r] 为中心能扩展出的最长回文长度
  // （相当于区间 DP dp[i][j] 空间优化后的等价形式）
  const n = s.length;
  const expand = (l, r) => {           // 向两侧扩展
    while (l >= 0 && r < n && s[l] === s[r]) { l--; r++; }
    return r - l - 1;                  // 循环结束时已不回文，长度为 r-l-1
  };
  let start = 0, end = 0;              // 记录当前最长回文的左右端点
  for (let i = 0; i < n; i++) {
    const m = Math.max(expand(i, i), expand(i, i + 1));   // 字符位/间隙两种中心
    if (m > end - start + 1) {         // 发现更长的回文则更新端点
      start = i - Math.floor((m - 1) / 2);
      end = i + Math.floor(m / 2);
    }
  }
  return s.slice(start, end + 1);
};

problems.codeGo:
func longestPalindrome(s string) string {
	// 状态定义：expand(l, r) 返回以 s[l..r] 为中心能扩展出的最长回文长度
	// （相当于区间 DP dp[i][j] 空间优化后的等价形式）
	n := len(s)
	expand := func(l, r int) int {   // 向两侧扩展
		for l >= 0 && r < n && s[l] == s[r] {
			l--
			r++
		}
		return r - l - 1              // 循环结束时已不回文，长度为 r-l-1
	}
	start, end := 0, 0                // 记录当前最长回文的左右端点
	for i := 0; i < n; i++ {
		odd := expand(i, i)           // 奇数长度回文：中心是一个字符
		even := expand(i, i+1)        // 偶数长度回文：中心是字符间隙
		m := odd
		if even > m {
			m = even
		}
		if m > end-start+1 {          // 发现更长的回文则更新端点
			start = i - (m-1)/2
			end = i + m/2
		}
	}
	return s[start : end+1]
}

