def unique_paths_memo(m, n):
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def f(i, j):
        if i == 0 or j == 0:
            return 1                  # 首行首列只有一条直路
        return f(i - 1, j) + f(i, j - 1)   # 上方来 + 左方来
    return f(m - 1, n - 1)

def unique_paths_table(m, n):
    dp = [[1] * n for _ in range(m)]  # 首行首列全 1
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1]   # 上方 + 左方
    return dp[m - 1][n - 1]

def unique_paths_rolling(m, n):
    f = [1] * n                       # 第 0 行：路径数全为 1
    for i in range(1, m):
        for j in range(1, n):         # 正序：f[j-1] 是本行新值
            f[j] += f[j - 1]          # f[j] 旧值=上方，f[j-1]=左方
    return f[n - 1]

import math

def unique_paths_math(m, n):
    # 路径 = m-1 个下步 + n-1 个右步的排列数，即 C(m+n-2, m-1)
    return math.comb(m + n - 2, m - 1)

