class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        # 状态定义：f[j] 表示走到当前行第 j 列的不同路径数（滚动压缩自 dp[i][j]）
        f = [1] * n               # 第 0 行：只能一路向右，路径数全为 1
        for i in range(1, m):     # 从第 1 行开始逐行递推
            for j in range(1, n):
                # 更新前 f[j] 是正上方 dp[i-1][j]，f[j-1] 是已更新的左方 dp[i][j-1]
                f[j] += f[j - 1]
        return f[n - 1]           # 右下角的路径数

