def min_path_sum_memo(grid):
    m, n = len(grid), len(grid[0])
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def f(i, j):
        if i < 0 or j < 0:
            return float('inf')       # 越界不可达
        if i == 0 and j == 0:
            return grid[0][0]         # 起点
        return grid[i][j] + min(f(i - 1, j), f(i, j - 1))
    return f(m - 1, n - 1)

