class Solution {
public:
    int minPathSum(vector<vector<int>>& grid) {
        // 状态定义：f[j] 表示从 (0,0) 走到当前行第 j 列的最小路径和（滚动自 dp[i][j]）
        int m = (int)grid.size(), n = (int)grid[0].size();
        vector<int> f(n, 0);
        f[0] = grid[0][0];
        for (int j = 1; j < n; ++j)      // 第 0 行：只能从左来，做前缀和
            f[j] = f[j - 1] + grid[0][j];
        for (int i = 1; i < m; ++i) {    // 逐行向下递推
            f[0] += grid[i][0];          // 第 0 列：只能从上来
            for (int j = 1; j < n; ++j)
                // f[j] 旧值 = 上方 dp[i-1][j]，f[j-1] 新值 = 左方 dp[i][j-1]
                f[j] = min(f[j], f[j - 1]) + grid[i][j];
        }
        return f[n - 1];
    }
};

