def min_distance_memo(word1, word2):
    m, n = len(word1), len(word2)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def f(i, j):
        if i == 0:
            return j                  # word1 空：插入 j 个字符
        if j == 0:
            return i                  # word2 空：删除 i 个字符
        if word1[i - 1] == word2[j - 1]:
            return f(i - 1, j - 1)    # 末字符相同：无需操作
        # 替换 / 删除 / 插入，三种末尾处置取最小再 +1
        return 1 + min(f(i - 1, j - 1), f(i - 1, j), f(i, j - 1))
    return f(m, n)

def min_distance_table(word1, word2):
    m, n = len(word1), len(word2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i                  # 变空串：删除 i 个字符
    for j in range(n + 1):
        dp[0][j] = j                  # 从空串变来：插入 j 个字符
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]     # 末字符相同：免费继承
            else:
                dp[i][j] = 1 + min(dp[i - 1][j - 1],   # 替换
                                   dp[i - 1][j],       # 删除
                                   dp[i][j - 1])       # 插入
    return dp[m][n]

def min_distance_rolling(word1, word2):
    m, n = len(word1), len(word2)
    f = list(range(n + 1))            # 第 0 行：dp[0][j] = j
    for i in range(1, m + 1):
        prev = f[0]                   # prev 暂存左上角 dp[i-1][j-1]
        f[0] = i                      # 第 0 列：dp[i][0] = i
