def is_interleave_memo(s1, s2, s3):
    m, n = len(s1), len(s2)
    if m + n != len(s3):
        return False                  # 长度不匹配直接剪枝
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def f(i, j):
        if i == 0 and j == 0:
            return True               # 空对空
        ok = False
        if i > 0 and s1[i - 1] == s3[i + j - 1]:   # 末字符取自 s1
            ok = f(i - 1, j)
        if not ok and j > 0 and s2[j - 1] == s3[i + j - 1]:   # 取自 s2
            ok = f(i, j - 1)
        return ok
    return f(m, n)

