class Solution {
public:
    bool isInterleave(string s1, string s2, string s3) {
        // 状态定义：f[j] = s1 前 i 个与 s2 前 j 个能否交错组成 s3 前 i+j 个字符（滚动自 dp[i][j]）
        int m = (int)s1.size(), n = (int)s2.size();
        if (m + n != (int)s3.size())     // 长度不匹配必然无法组成，提前剪枝
            return false;
        vector<bool> f(n + 1, false);
        f[0] = true;                     // 空串组成空串
        for (int j = 1; j <= n; ++j)     // 只用 s2 组成 s3 前缀的情形（第 0 行）
            f[j] = f[j - 1] && s2[j - 1] == s3[j - 1];
        for (int i = 1; i <= m; ++i) {
            f[0] = f[0] && s1[i - 1] == s3[i - 1];   // 只用 s1 组成的第 0 列
            for (int j = 1; j <= n; ++j) {
                // f[j] 旧值 = 上一行 dp[i-1][j]（末字符取自 s1）
                bool use_s1 = f[j] && s1[i - 1] == s3[i + j - 1];
                // f[j-1] 新值 = 本行左格 dp[i][j-1]（末字符取自 s2）
                bool use_s2 = f[j - 1] && s2[j - 1] == s3[i + j - 1];
                f[j] = use_s1 || use_s2;
            }
        }
        return f[n];
    }
};

