def num_distinct_memo(s, t):
    m, n = len(s), len(t)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def f(i, j):
        if j == 0:
            return 1                  # 空 t：全不选，恰有一种匹配
        if i < j:
            return 0                  # s 剩余不够长，剪枝
        # 不用 s[i-1]；相等时再累加用它配 t[j-1] 的方案
        return f(i - 1, j) + (f(i - 1, j - 1) if s[i - 1] == t[j - 1] else 0)
    return f(m, n)

def num_distinct_table(s, t):
    m, n = len(s), len(t)
    if n > m:
        return 0
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = 1                  # 空 t 有一种『全不选』匹配
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            dp[i][j] = dp[i - 1][j]   # 不用 s[i-1]
            if s[i - 1] == t[j - 1]:
                dp[i][j] += dp[i - 1][j - 1]   # 用 s[i-1] 配 t[j-1]
    return dp[m][n]

def num_distinct_rolling(s, t):
    m, n = len(s), len(t)
    if n > m:
        return 0
    f = [0] * (n + 1)
    f[0] = 1                          # 空 t 的锚点：一种『全不选』匹配
    for i in range(1, m + 1):
        for j in range(n, 0, -1):     # 倒序！f[j-1] 保持为上一行的值
            if s[i - 1] == t[j - 1]:
                f[j] += f[j - 1]      # 不用（f[j] 旧值）+ 用（f[j-1] 旧值）
    return f[n]

