    return dfs(n, target)

def can_partition_table(nums):
    total = sum(nums)
    if total % 2:
        return False                  # 奇数无法平分
    target = total // 2
    n = len(nums)
    dp = [[False] * (target + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = True               # 凑 0：全不选
    for i in range(1, n + 1):
        x = nums[i - 1]
        for j in range(1, target + 1):
            dp[i][j] = dp[i - 1][j]   # 不选 x
            if j >= x:
                dp[i][j] = dp[i][j] or dp[i - 1][j - x]   # 选 x
    return dp[n][target]

