def change_memo(amount, coins):
    n = len(coins)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dfs(i, remain):
        if remain == 0:
            return 1                  # 凑出一种组合
        if remain < 0 or i == n:
            return 0                  # 凑超 / 面额用尽
        # 不用第 i 种 + 用一枚第 i 种（i 不前移：还能继续用）
        return dfs(i + 1, remain) + dfs(i, remain - coins[i])
    return dfs(0, amount)

def change_table(amount, coins):
    n = len(coins)
    dp = [[0] * (amount + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 1                  # 凑 0 元：一种方案（什么都不选）
    for i in range(1, n + 1):
        c = coins[i - 1]
        for j in range(1, amount + 1):
            dp[i][j] = dp[i - 1][j]           # 不用第 i 种
            if j >= c:
                dp[i][j] += dp[i][j - c]      # 再用一枚第 i 种（同行=无限量）
    return dp[n][amount]

