class Solution {
public:
    int change(int amount, vector<int>& coins) {
        // 状态定义：dp[j] = 用已遍历的面额凑出金额 j 的组合数（完全背包计数）
        vector<long long> dp(amount + 1, 0);   // 组合数可能很大，用 long long 防止溢出
        dp[0] = 1;                       // 凑 0 元只有『什么都不选』一种方案
        for (int coin : coins) {         // 外层硬币：保证只数组合、不数排列
            for (int j = coin; j <= amount; ++j) {   // 内层正序：同一硬币可重复使用
                // 新增方案 = 先前凑出 j-coin 的每种组合再放一枚 coin
                dp[j] += dp[j - coin];
            }
        }
        return (int)dp[amount];
    }
};

