def max_profit_memo(prices):
    n = len(prices)
    from functools import lru_cache
    HOLD, SOLD, REST = 0, 1, 2        # 持有 / 当天刚卖出 / 空仓观望
    @lru_cache(maxsize=None)
    def dfs(i, state):
        if i == 0:
            return -prices[0] if state == HOLD else 0   # 首日：买入或空仓
        p = prices[i]
        if state == HOLD:
            # 昨天就持有不动，或昨天空仓（冷冻期已过）今天买入
            return max(dfs(i - 1, HOLD), dfs(i - 1, REST) - p)
        if state == SOLD:
            return dfs(i - 1, HOLD) + p     # 昨天持有今天卖出
        return max(dfs(i - 1, REST), dfs(i - 1, SOLD))   # 观望 / 昨卖今歇
    return max(dfs(n - 1, SOLD), dfs(n - 1, REST))   # 收官必须空仓

def max_profit_rolling(prices):
    hold, sold, rest = -prices[0], 0, 0   # 首日：买入 / 卖出态 / 空仓
    for price in prices[1:]:
        # 元组右端全读昨天的旧值，一次性滚动
        hold, sold, rest = max(hold, rest - price), hold + price, max(rest, sold)
    return max(sold, rest)            # 收官必须空仓

