def max_profit_memo(prices, fee):
    n = len(prices)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dfs(i, holding):
        if i == n:
            return 0 if not holding else float('-inf')   # 收官必须空仓
        p = prices[i]
        if holding:
            # 继续持有 or 今天卖出（扣手续费）
            return max(dfs(i + 1, True), p - fee + dfs(i + 1, False))
        # 继续空仓 or 今天买入
        return max(dfs(i + 1, False), -p + dfs(i + 1, True))
    return dfs(0, False)

def max_profit_rolling(prices, fee):
    cash, hold = 0, -prices[0]        # 空仓利润 / 持股利润
    for price in prices[1:]:
        # 元组同时赋值保证两边都读昨天的旧值，避免同日先卖再买
        cash, hold = max(cash, hold + price - fee), max(hold, cash - price)
    return cash                       # 最优策略收官必然空仓

