def lcs_memo(text1, text2):
    m, n = len(text1), len(text2)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def f(i, j):
        if i == 0 or j == 0:
            return 0                  # 与空串无公共子序列
        if text1[i - 1] == text2[j - 1]:
            return f(i - 1, j - 1) + 1     # 末字符配成一对
        return max(f(i - 1, j), f(i, j - 1))   # 丢掉一个末尾
    return f(m, n)

def lcs_table(text1, text2):
    m, n = len(text1), len(text2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]   # 第 0 行/列全 0
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i - 1] == text2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

def lcs_rolling(text1, text2):
    m, n = len(text1), len(text2)
    f = [0] * (n + 1)                 # 第 0 行：与空串的 LCS 为 0
    for i in range(1, m + 1):
        prev = 0                      # 行首的左上角 dp[i-1][0] = 0
        for j in range(1, n + 1):
            cur = f[j]                # 暂存 dp[i-1][j]，下一列的左上角
            if text1[i - 1] == text2[j - 1]:
                f[j] = prev + 1       # 末字符配对：对角线 + 1
            else:
                f[j] = max(f[j], f[j - 1])   # 上方 vs 左方
            prev = cur
    return f[n]

